{page==='Craft Categories'&&<>{header('Craft Categories',`Manage ${categories.length} specialized disciplines across the Indian film industry.`,<Button onClick={()=>open('category')}>{icon('Plus',17)} Add Category</Button>)}<div className="toolbar"><div className="search-box">{icon('Search',17)}<input placeholder="Search craft categories..." value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All</option><option>Active</option><option>Inactive</option></select><div className="toggle"><button className={view==='grid'?'on':''} onClick={()=>setView('grid')}>{icon('LayoutGrid',17)}</button><button className={view==='list'?'on':''} onClick={()=>setView('list')}>{icon('List',17)}</button></div></div><div className={view==='grid'?'category-grid':'category-list'}>{categories.filter(c=>c.name.toLowerCase().includes(search.toLowerCase())&&(filter==='All'||(c.active?'Active':'Inactive')===filter)).map((c,i)=><div className="category-card" key={c.id}><div className="category-top"><span className={'category-symbol c'+i%6}>{icon(['Clapperboard','Camera','Scissors','Film','Palette','PenTool','Music','AudioLines','Sparkles','MonitorPlay'][i%10],24)}</span><Badge value={c.active?'Active':'Inactive'}/></div><h3>{c.name}</h3><p>{c.description}</p><div className="category-foot"><span>{icon('Users',15)} {c.count.toLocaleString()} professionals</span><div className="actions"><button title="View details" onClick={()=>open('category-details',c)}>{icon('Eye',16)}</button><button title="Edit" onClick={()=>open('category',c)}>{icon('Pencil',16)}</button><button title="Delete" onClick={()=>open('delete-category',c)}>{icon('Trash2',16)}</button></div></div></div>)}</div></>}
